// Package installsh tests install.sh against a local HTTPS "release"
// signed with a minisign key generated by the test (FR-13.2, and the
// security review's RR-01 cosign check).
package installsh

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/pem"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"

	"aead.dev/minisign"

	"github.com/ethan03805/secure-mcp-gateway/internal/reqtest"
)

const version = "9.9.9"

var (
	archiveName = fmt.Sprintf("smcp_%s_%s_%s.tar.gz", version, runtime.GOOS, runtime.GOARCH)
	sumsName    = fmt.Sprintf("smcp_%s_checksums.txt", version)
	binaries    = map[string]string{"smcpd": "#!/bin/sh\necho smcpd test\n", "smcpctl": "#!/bin/sh\necho smcpctl test\n"}
)

func tgz(t *testing.T, files map[string]string) []byte {
	t.Helper()
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gz)
	for name, body := range files {
		if err := tw.WriteHeader(&tar.Header{Name: name, Mode: 0o755, Size: int64(len(body)), ModTime: time.Unix(0, 0)}); err != nil {
			t.Fatal(err)
		}
		if _, err := tw.Write([]byte(body)); err != nil {
			t.Fatal(err)
		}
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := gz.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func sumLine(b []byte, name string) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:]) + "  " + name + "\n"
}

// release is the set of files the HTTPS server serves.
type release map[string][]byte

func signPrehashed(priv minisign.PrivateKey, msg []byte, comment string) []byte {
	r := minisign.NewReader(bytes.NewReader(msg))
	_, _ = r.Read(make([]byte, len(msg)+1))
	return r.SignWithComments(priv, comment, "signature from test key")
}

// newRelease builds an intact signed release and returns it with the
// public key.
func newRelease(t *testing.T, legacy bool) (release, minisign.PrivateKey, string) {
	t.Helper()
	pub, priv, err := minisign.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	arc := tgz(t, binaries)
	sums := []byte(sumLine(arc, archiveName) + sumLine([]byte("other"), "smcp_9.9.9_linux_s390x.tar.gz"))
	comment := "smcp " + version + " file:" + sumsName
	var sig []byte
	if legacy {
		sig = minisign.SignWithComments(priv, sums, comment, "signature from test key")
	} else {
		sig = signPrehashed(priv, sums, comment)
	}
	return release{archiveName: arc, sumsName: sums, sumsName + ".minisig": sig}, priv, pub.String()
}

// toolFarm makes a PATH directory with links to the host tools install.sh
// needs, plus the extra names given (when the host has them).
func toolFarm(t *testing.T, extra ...string) string {
	t.Helper()
	dir := t.TempDir()
	base := []string{"sh", "uname", "tar", "gzip", "mktemp", "od", "curl", "sha256sum", "shasum", "perl", "awk", "cut", "sed", "tr",
		"head", "tail", "dd", "cat", "cp", "chmod", "mv", "mkdir", "rm", "id", "wc", "env", "dirname", "basename", "ls"}
	for _, name := range append(base, extra...) {
		p, err := exec.LookPath(name)
		if err != nil {
			continue
		}
		if err := os.Symlink(p, filepath.Join(dir, name)); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := os.Stat(filepath.Join(dir, "curl")); err != nil {
		t.Skip("curl is not installed")
	}
	return dir
}

// openssl3 returns an OpenSSL 3 binary, or "".
func openssl3() string {
	for _, p := range []string{"openssl", "/opt/homebrew/opt/openssl@3/bin/openssl", "/usr/local/opt/openssl@3/bin/openssl"} {
		if lp, err := exec.LookPath(p); err == nil {
			out, _ := exec.Command(lp, "version").Output()
			if bytes.HasPrefix(out, []byte("OpenSSL 3")) || bytes.HasPrefix(out, []byte("OpenSSL 4")) {
				return lp
			}
		}
	}
	return ""
}

type result struct {
	out     string
	err     error
	dir     string // --dir
	home    string
	tmp     string
	cosignA string // arguments the fake cosign received
}

// runInstall serves rel over HTTPS and runs install.sh with PATH=farm.
func runInstall(t *testing.T, rel release, pubkey, farm string, args ...string) result {
	t.Helper()
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b, ok := rel[strings.TrimPrefix(r.URL.Path, "/rel/")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		_, _ = w.Write(b)
	}))
	defer srv.Close()
	work := t.TempDir()
	ca := filepath.Join(work, "ca.pem")
	if err := os.WriteFile(ca, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: srv.Certificate().Raw}), 0o600); err != nil {
		t.Fatal(err)
	}
	res := result{dir: filepath.Join(work, "bin"), home: filepath.Join(work, "home"), tmp: filepath.Join(work, "tmp")}
	for _, d := range []string{res.home, res.tmp} {
		if err := os.Mkdir(d, 0o700); err != nil {
			t.Fatal(err)
		}
	}
	cosignLog := filepath.Join(work, "cosign.args")
	argv := append([]string{filepath.Join("..", "..", "install.sh"), "--version", "v" + version, "--base-url", srv.URL + "/rel/",
		"--pubkey", pubkey, "--dir", res.dir}, args...)
	cmd := exec.Command(filepath.Join(farm, "sh"), argv...)
	cmd.Env = []string{"PATH=" + farm, "HOME=" + res.home, "TMPDIR=" + res.tmp, "CURL_CA_BUNDLE=" + ca, "SSL_CERT_FILE=" + ca,
		"COSIGN_LOG=" + cosignLog, "LC_ALL=C"}
	out, err := cmd.CombinedOutput()
	res.out, res.err = string(out), err
	if b, err := os.ReadFile(cosignLog); err == nil {
		res.cosignA = string(b)
	}
	return res
}

// installedNothing checks that a refused run left no file outside its
// (removed) temporary directory.
func installedNothing(t *testing.T, r result) {
	t.Helper()
	if r.err == nil {
		t.Fatalf("install.sh succeeded:\n%s", r.out)
	}
	if _, err := os.Stat(r.dir); err == nil {
		t.Fatalf("install directory %s was created:\n%s", r.dir, r.out)
	}
	for _, d := range []string{r.home, r.tmp} {
		if entries, _ := os.ReadDir(d); len(entries) != 0 {
			t.Fatalf("%s holds %v after a refused install:\n%s", d, entries, r.out)
		}
	}
}

func installed(t *testing.T, r result) {
	t.Helper()
	if r.err != nil {
		t.Fatalf("install.sh: %v\n%s", r.err, r.out)
	}
	for name, body := range binaries {
		b, err := os.ReadFile(filepath.Join(r.dir, name))
		if err != nil || string(b) != body {
			t.Fatalf("%s not installed: %v\n%s", name, err, r.out)
		}
	}
	if entries, _ := os.ReadDir(r.tmp); len(entries) != 0 {
		t.Fatalf("temporary files left: %v", entries)
	}
}

func clone(r release) release {
	c := release{}
	for k, v := range r {
		c[k] = append([]byte(nil), v...)
	}
	return c
}

func TestInstallScriptVerifiesSignatureAndChecksum(t *testing.T) {
	// FR-13.2: through a real HTTPS download, a modified archive and a
	// modified checksum file are refused with nothing written outside the
	// script's temporary directory, and the intact release installs; with
	// the minisign CLI (when the host has it) and with the OpenSSL 3
	// fallback (when the host has it).
	reqtest.Verifies(t, "FR-13.2")
	type verifier struct{ name, tool string }
	var vs []verifier
	if _, err := exec.LookPath("minisign"); err == nil {
		vs = append(vs, verifier{"minisign", "minisign"})
	}
	if o := openssl3(); o != "" {
		vs = append(vs, verifier{"openssl3", o})
	}
	if len(vs) == 0 {
		t.Skip("neither minisign nor OpenSSL 3 is installed")
	}
	for _, v := range vs {
		for _, legacy := range []bool{false, true} {
			t.Run(fmt.Sprintf("%s/legacy=%v", v.name, legacy), func(t *testing.T) {
				farm := toolFarm(t)
				tool, link := v.tool, "openssl"
				if v.name == "minisign" {
					tool, _ = exec.LookPath("minisign")
					link = "minisign"
				}
				if err := os.Symlink(tool, filepath.Join(farm, link)); err != nil {
					t.Fatal(err)
				}
				rel, priv, pk := newRelease(t, legacy)

				r := runInstall(t, rel, pk, farm)
				installed(t, r)
				if !strings.Contains(r.out, "with "+link) {
					t.Fatalf("verifier %s not reported:\n%s", link, r.out)
				}
				if !strings.Contains(r.out, "cosign is not installed") {
					t.Fatalf("missing cosign notice:\n%s", r.out)
				}

				// Modified archive: the signature holds, the checksum does not.
				bad := clone(rel)
				bad[archiveName] = append(bad[archiveName], 0)
				r = runInstall(t, bad, pk, farm)
				installedNothing(t, r)
				if !strings.Contains(r.out, "checksum mismatch") {
					t.Fatalf("modified archive:\n%s", r.out)
				}

				// Modified checksum file (re-pointed at the modified archive):
				// the signature fails.
				bad2 := clone(bad)
				bad2[sumsName] = []byte(sumLine(bad[archiveName], archiveName))
				r = runInstall(t, bad2, pk, farm)
				installedNothing(t, r)
				if !strings.Contains(r.out, "does not verify") {
					t.Fatalf("modified checksum file:\n%s", r.out)
				}

				// Another key's public key.
				otherPub, _, _ := minisign.GenerateKey(rand.Reader)
				r = runInstall(t, rel, otherPub.String(), farm)
				installedNothing(t, r)

				// No signature file.
				nosig := clone(rel)
				delete(nosig, sumsName+".minisig")
				r = runInstall(t, nosig, pk, farm)
				installedNothing(t, r)

				// A valid signature over the checksum file whose trusted
				// comment names another release's file.
				replay := clone(rel)
				replay[sumsName+".minisig"] = signPrehashed(priv, rel[sumsName], "file:smcp_1.0.0_checksums.txt")
				r = runInstall(t, replay, pk, farm)
				installedNothing(t, r)
				if !strings.Contains(r.out, "does not name") {
					t.Fatalf("replayed comment:\n%s", r.out)
				}
			})
		}
	}
}

func TestInstallScriptNoVerifier(t *testing.T) {
	reqtest.Partial(t, "FR-13.2")
	for _, p := range []string{"/opt/homebrew/opt/openssl@3/bin/openssl", "/usr/local/opt/openssl@3/bin/openssl"} {
		if _, err := os.Stat(p); err == nil {
			t.Skip("install.sh finds " + p + " by its absolute path")
		}
	}
	farm := toolFarm(t) // neither minisign nor openssl
	rel, _, pk := newRelease(t, false)
	r := runInstall(t, rel, pk, farm)
	installedNothing(t, r)
	if !strings.Contains(r.out, "cannot verify the release signature") {
		t.Fatal(r.out)
	}
}

func TestInstallScriptCosign(t *testing.T) {
	// RR-01 (docs/security-review-2026-10.md): with cosign installed the
	// Sigstore bundle must verify against the release workflow identity.
	// cosign is faked; the real keyless verification needs a release.
	reqtest.Partial(t, "FR-13.2")
	tool := ""
	if _, err := exec.LookPath("minisign"); err == nil {
		tool = "minisign"
	} else if o := openssl3(); o != "" {
		tool = o
	} else {
		t.Skip("neither minisign nor OpenSSL 3 is installed")
	}
	fake := func(t *testing.T, code int) string {
		farm := toolFarm(t)
		if tool == "minisign" {
			p, _ := exec.LookPath("minisign")
			_ = os.Symlink(p, filepath.Join(farm, "minisign"))
		} else {
			_ = os.Symlink(tool, filepath.Join(farm, "openssl"))
		}
		script := fmt.Sprintf("#!/bin/sh\necho \"$@\" > \"$COSIGN_LOG\"\nexit %d\n", code)
		if err := os.WriteFile(filepath.Join(farm, "cosign"), []byte(script), 0o755); err != nil {
			t.Fatal(err)
		}
		return farm
	}
	rel, _, pk := newRelease(t, false)
	rel[sumsName+".sigstore.json"] = []byte(`{"test":"bundle"}`)

	r := runInstall(t, rel, pk, fake(t, 0))
	installed(t, r)
	for _, want := range []string{"verify-blob", "--bundle", "--certificate-identity-regexp ^https://github.com/ethan03805/Secure-MCP-Gateway/.github/workflows/release.yml@",
		"--certificate-oidc-issuer https://token.actions.githubusercontent.com", sumsName} {
		if !strings.Contains(r.cosignA, want) {
			t.Fatalf("cosign arguments lack %q: %s", want, r.cosignA)
		}
	}
	if !strings.Contains(r.out, "Sigstore bundle verified") {
		t.Fatal(r.out)
	}

	r = runInstall(t, rel, pk, fake(t, 1))
	installedNothing(t, r)
	if !strings.Contains(r.out, "cosign could not verify") {
		t.Fatal(r.out)
	}

	nobundle := clone(rel)
	delete(nobundle, sumsName+".sigstore.json")
	r = runInstall(t, nobundle, pk, fake(t, 0))
	installedNothing(t, r)

	r = runInstall(t, nobundle, pk, fake(t, 1), "--no-cosign")
	installed(t, r)
	if r.cosignA != "" || !strings.Contains(r.out, "cosign check skipped") {
		t.Fatalf("--no-cosign ran cosign: %q\n%s", r.cosignA, r.out)
	}
}

func TestInstallScriptEmbedsPublishedKey(t *testing.T) {
	// The key embedded in install.sh is the one published in SECURITY.md
	// and docs/install.md.
	script, err := os.ReadFile(filepath.Join("..", "..", "install.sh"))
	if err != nil {
		t.Fatal(err)
	}
	var key string
	for _, l := range strings.Split(string(script), "\n") {
		if strings.HasPrefix(l, `PUBKEY="`) {
			key = strings.TrimSuffix(strings.TrimPrefix(l, `PUBKEY="`), `"`)
		}
	}
	var pub minisign.PublicKey
	if err := pub.UnmarshalText([]byte(key)); err != nil {
		t.Fatalf("install.sh PUBKEY %q: %v", key, err)
	}
	for _, f := range []string{"SECURITY.md", "docs/install.md", "docs/release-checklist.md"} {
		b, err := os.ReadFile(filepath.Join("..", "..", f))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(string(b), key) {
			t.Errorf("%s does not publish the release key %s", f, key)
		}
	}
}

func TestInstallScriptOpenSSLAcceptsMinisignCLISignature(t *testing.T) {
	// The release workflow signs with the minisign CLI (GoReleaser signs
	// stanza); the OpenSSL 3 fallback must accept what that CLI writes.
	reqtest.Partial(t, "FR-13.2")
	mini, err := exec.LookPath("minisign")
	if err != nil {
		t.Skip("minisign is not installed")
	}
	o := openssl3()
	if o == "" {
		t.Skip("OpenSSL 3 is not installed")
	}
	keys := t.TempDir()
	pubFile, secFile := filepath.Join(keys, "k.pub"), filepath.Join(keys, "k.key")
	if out, err := exec.Command(mini, "-G", "-W", "-p", pubFile, "-s", secFile).CombinedOutput(); err != nil {
		t.Fatalf("minisign -G: %v\n%s", err, out)
	}
	rel, _, _ := newRelease(t, false)
	sums := filepath.Join(keys, sumsName)
	if err := os.WriteFile(sums, rel[sumsName], 0o600); err != nil {
		t.Fatal(err)
	}
	// The arguments of the minisign signer in .goreleaser.yaml.
	cmd := exec.Command(mini, "-S", "-s", secFile, "-m", sums, "-x", sums+".minisig", "-t", "smcp "+version+" file:"+sumsName)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("minisign -S: %v\n%s", err, out)
	}
	sig, err := os.ReadFile(sums + ".minisig")
	if err != nil {
		t.Fatal(err)
	}
	rel[sumsName+".minisig"] = sig
	pubText, err := os.ReadFile(pubFile)
	if err != nil {
		t.Fatal(err)
	}
	lines := strings.Split(strings.TrimSpace(string(pubText)), "\n")
	farm := toolFarm(t)
	if err := os.Symlink(o, filepath.Join(farm, "openssl")); err != nil {
		t.Fatal(err)
	}
	r := runInstall(t, rel, lines[len(lines)-1], farm)
	installed(t, r)
	if !strings.Contains(r.out, "with openssl") {
		t.Fatal(r.out)
	}
}
